package com.yeyamo_mobile.api.referral_service.application;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import org.springframework.stereotype.Component;
@Component public class HashingService{public String email(String value){return sha256(value.trim().toLowerCase(java.util.Locale.ROOT));}public String fingerprint(String value){return value==null||value.isBlank()?null:sha256(value.trim());}String sha256(String value){try{byte[]bytes=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));return java.util.HexFormat.of().formatHex(bytes);}catch(Exception e){throw new IllegalStateException(e);}}}
